[
  {
    "severity": "P0毁容级",
    "category": "ua-default-style",
    "description": "卡片标题区域（包含“报”、“AI”、“本月经营概览”等元素）外围包裹了厚重的黑色直角边框，疑似为浏览器默认的 focus 环或未清除的容器边框残留，严重背离“酱园琥珀”的温润调性。",
    "suggestion": "移除该黑色直角边框，若需分割感，可采用极细的酱色描边或通过色块区分。"
  },
  {
    "severity": "P1明显",
    "category": "other",
    "description": "顶部返回按钮、标题栏边框及部分图标使用纯黑色，与设计语言要求的“酱色（深棕红）”主色冲突，呈现出冷硬的工业感。",
    "suggestion": "将全站纯黑（#000000）元素统一替换为酱色（深棕红），以符合“酱园琥珀”视觉规范。"
  },
  {
    "severity": "P2瑕疵",
    "category": "misalign",
    "description": "卡片内部对齐方式不统一：头部元素为左对齐，而描述性文本（“截至今天...”）与操作项（“查看报告”）为居中对齐，视觉轴线断裂。",
    "suggestion": "建议将卡片内所有元素统一为左对齐，或将操作项右对齐以平衡视觉重心。"
  },
  {
    "severity": "P2瑕疵",
    "category": "contrast",
    "description": "中间辅助信息“截至今天 · 数据来自湖仓指标 10/05”字号偏小且颜色较淡，在暖色纸感背景上的易读性较差。",
    "suggestion": "适当加深该部分文字的灰度或增大 1-2px 字号以提升可读性。"
  },
  {
    "severity": "P2瑕疵",
    "category": "spacing",
    "description": "“AI 生成”、“最近文件”、“收藏”三个大标题与上方卡片的间距过大，导致页面结构松散，缺乏逻辑聚合感。",
    "suggestion": "收紧段落间距，增强标题与其下方所属卡片内容的关联性。"
  }
]
